mapper.select:
SELECT *
FROM lunaerp_finance_account
WHERE id = #{id}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_finance_account
SET deleted = 0,
    updater = #{updater},
    update_time = #{now}
WHERE id = #{id}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_finance_account
WHERE id = #{id}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.select:
SELECT COUNT(1)
FROM lunaerp_finance_ledger_entry
WHERE account_id = #{id}
  AND deleted = 0
  AND tenant_id = #{tenantId}
